import{_ as e,c as r,o as p,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"52、【艮】 艮下艮上","description":"周易尚氏學 - 52、【艮】 艮下艮上","frontmatter":{"title":"52、【艮】 艮下艮上","description":"周易尚氏學 - 52、【艮】 艮下艮上"},"headers":[],"relativePath":"classics/shangshi/057.md","filePath":"classics/shangshi/057.md"}'),s={name:"classics/shangshi/057.md"};function h(t,a,l,n,c,d){return p(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_52、【艮】-艮下艮上" tabindex="-1">52、【艮】 艮下艮上 <a class="header-anchor" href="#_52、【艮】-艮下艮上" aria-label="Permalink to “52、【艮】 艮下艮上”">​</a></h1><p>艮其背。不獲其身。行其庭。不見其人。無咎。歸藏作狠。狠廣韻很之俗宇。說文很不聽從也。一曰行難也。艮鄭雲艮之言很也。是很艮義同。艮止也。震為行。震反故止。雜卦震起也。艮止也。即言正反之義也。舊說以陽在上為止。非其義也。艮為背為身為庭為人。艮其背。靜也。三至五互震。故又曰行其庭。行其庭動也。乃因無應與。靜則不獲身上手足之用。動則不見庭除應予之人。無動作無交際。故亦無咎也。</p><p>彖曰。艮。止也。時止則止。時行則行。動靜不失其時。其道光明。艮其止。止其所也。上下敵應。不相與也。是以不獲其身。行其庭不見其人。無咎也。</p><p>艮為時。下艮。故曰時止則止。三至五互震。故曰時行則行。止則靜。行則動。動靜隨時。故其道光明。艮為道路。陽在上故光明。六爻無應予。故曰敵應。陰陽相遇為朋為類。若陽遇陽。陰遇陰。則皆為敵。同人九三雲。敵剛。以比應皆陽。故曰敵剛。以陽遇陽為敵。中孚六三雲。得敵。子夏傳雲。四與三為敵。而不釋其義。荀爽解之曰。三四俱陰。故稱敵也。以陰遇陰為敵。此實易義之根本。明乎此則屯二之十年乃字。此三之比之匪人。頤六二之失類。六五之不利涉。大壯初九之徵兇。解九四這解而拇。夬初九之往不勝。九四之其行次且。鼎九二之慎所之。震六五之往厲。皆可觀象而得其義。否則不知其所謂矣。此易義之所以終古長夜也。然觀子夏傳之解得敵。似此義韓嬰已知之。荀爽能釋之。然可以於上列各爻。任其失解。抑有解而採輯者不合其意而不錄歟。</p><h3 id="象曰。兼山。艮。君子以思不出其位。" tabindex="-1">象曰。兼山。艮。君子以思不出其位。 <a class="header-anchor" href="#象曰。兼山。艮。君子以思不出其位。" aria-label="Permalink to “象曰。兼山。艮。君子以思不出其位。”">​</a></h3><p>艮為位，艮止故不出。坎為思。得中唯心亨。亦不出。學易之君子法之。</p><p>初六。艮其趾 無咎。利永貞。</p><p>爻例在下稱趾。足上不動。故無咎，利永貞者。利於永遠貞定也。著初失位無應遇敵。故貴於無為也。趾荀作止，止古文趾字。</p><h3 id="象曰。艮其趾。未失正也。" tabindex="-1">象曰。艮其趾。未失正也。 <a class="header-anchor" href="#象曰。艮其趾。未失正也。" aria-label="Permalink to “象曰。艮其趾。未失正也。”">​</a></h3><p>利永貞。故不失正。</p><p>六二。艮其用腓。 不拯其隨。其心不快。</p><p>腓。脛肚也。義詳鹹卦。腓之用在行。艮其腓。是不行也。拯京房作升。舉也。釋文作承。曰馬雲舉也。可證馬氏王氏本原作承。今作拯者。蓋開成以後所定。然升承拯音義並同。艮為手。故曰拯。艮止故不拯。然陰以順陽為天職。仍須隨陽。故曰不拯其隨。坎為心為優。既不可動。又須隨陽。不能自主。故其心不快。</p><h3 id="象曰。不拯其隨。未退聽也。" tabindex="-1">象曰。不拯其隨。未退聽也。 <a class="header-anchor" href="#象曰。不拯其隨。未退聽也。" aria-label="Permalink to “象曰。不拯其隨。未退聽也。”">​</a></h3><p>坎馬耳。故曰聽。聽從也。腓之用在動而前進。不拯是不動不前。而退聽也。然陽在上。義必隨行。是又不能退聽也。進退不克自主。故心不快也。</p><p>九三。艮其限。列其夤。厲燻心。</p><p>限。說文阻也。玉篇界也。即脊骨界左右也。故馬荀鄭虞皆訓為要。三居卦中。坎為要。故取象於限。坎為脊為肉。故取明於夤。夤。馬虞皆以為夾脊肉。脊骨居中為限。脊肉左右分列。列裂同。墨子明鬼下雲。生列兕虎。荀子哀公問雲。兩驂列兩服人廄。注皆作裂。脊肉裂分左右。脊界其中。故曰裂其夤。皆坎象也。艮為火。互坎為心。故厲燻心。自坎肉象失傳。後懦皆不知噬嗑三四五三爻之肉象。及．此夤象何屬。自艮火象失傳。虞翻以艮為閽。讀紊為閽。謂古閽作燻字。並雲馬吉燻灼其心。未聞易道以坎水燻灼人者。豈知艮為火。馬氏所詁。正與易合。至荀氏以燻為動。讀作動。來知德。又云以三十年之功。始悟燻字之由於伏離。由斯證一象之失傳。可使名家易人人異詞。真可嘆也。艮火坎肉象。皆詳焦氏易詁。易林艮之無妄雲。。顛覆不制。痛燻我心。是焦亦作燻。</p><h3 id="象曰。艮其限。危燻心也。" tabindex="-1">象曰。艮其限。危燻心也。 <a class="header-anchor" href="#象曰。艮其限。危燻心也。" aria-label="Permalink to “象曰。艮其限。危燻心也。”">​</a></h3><p>厲危也。故曰危燻心。</p><p>六四。艮其身。無咎。</p><p>艮為身。見上彖。虞以坤為身為孕非也。初趾二腓。三要四身。按爻序自下而上。故象釋為躬。得位故無咎。</p><h3 id="象曰。艮其身。止諸躬也。" tabindex="-1">象曰。艮其身。止諸躬也。 <a class="header-anchor" href="#象曰。艮其身。止諸躬也。" aria-label="Permalink to “象曰。艮其身。止諸躬也。”">​</a></h3><p>艮為躬。躬即身也。三四居卦之中。故曰要。曰身。並無他義。虞氏謂五動乘四則妊身。以止諸躬為妊身。卦天離象。強命王爻。變成離。惑亂學。莫此為甚。</p><p>六五。艮其輔。言有序。悔亡。</p><p>輔。說文人頰車也。在頰之上。與牙車相對。春秋僖五年。輔車相依。注云。車牙車。疏牙車。牙下骨之名。在頰之下。蓋幾物人口。皆賴牙車載之。故名曰車。人慾嚼物。或言語。則牙動而上與輔對。故曰輔車相依。輔在上不動。故艮為輔。頤即用以取象。三至五震。震為言。上卦震反。故曰艮其輔。序者次也。言不紊也。三至五震。時而當言則言。四至上。震反。時而不當言。則言止矣。故曰言有序。詩大雅序賓以賢。言賓之位次。與其賢相當。秩然不亂也。言行君子之樞機。時言則言。時止則止。有序如是。故無悔也。虞氏易序作孚。言孚於上也。</p><h3 id="象曰。艮其輔。以中正也。" tabindex="-1">象曰。艮其輔。以中正也。 <a class="header-anchor" href="#象曰。艮其輔。以中正也。" aria-label="Permalink to “象曰。艮其輔。以中正也。”">​</a></h3><p>五中而不正。正字或疑衍。又或作正中。然未濟九二傳。中以行正也。大壯九二傳。大者正也。大謂九二。似亦不拘。</p><p>上九。敦艮吉。</p><p>敦與頓通。頓止也。易凡言敦。皆有止義。待義。義詳敦臨敦復。敦艮者。頓止於上也。下履重陰。故吉。</p><h3 id="象曰。敦艮之吉。以厚終也。" tabindex="-1">象曰。敦艮之吉。以厚終也。 <a class="header-anchor" href="#象曰。敦艮之吉。以厚終也。" aria-label="Permalink to “象曰。敦艮之吉。以厚終也。”">​</a></h3><p>艮為山。故曰厚。而艮為終。故曰以厚終。唯厚故止也。</p>',30)])])}const f=e(s,[["render",h]]);export{_ as __pageData,f as default};
